 23→)
 24→
 25→// WriteCommitted writes a committed checkpoint to both v2 refs:
 26→//   - /main: metadata, prompts, content hash (no raw transcript)
 27→//   - /full/current: raw transcript only (replaces previous content)
 28→//
 29→// This is the public entry point for v2 dual-writes. The session index is
 30→// determined from the /main ref and passed to the /full/current write to
 31→// keep both refs consistent.
 32→func (s *V2GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
 33→	sessionIndex, err := s.writeCommittedMain(ctx, opts)
 34→	if err != nil {
 35→		return fmt.Errorf("v2 /main write failed: %w", err)
 36→	}
 37→
 38→	if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 39→		return fmt.Errorf("v2 /full/current write failed: %w", err)
 40→	}
 41→
 42→	return nil
 43→}
 44→
 45→// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
 46→// Called at stop time to finalize checkpoints with the complete session transcript.
 47→//
 48→// On /main: replaces prompts (transcript is not stored there).
 49→// On /full/current: replaces the raw transcript (if provided).
 50→//
 51→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
 52→func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
 53→	if opts.CheckpointID.IsEmpty() {
 54→		return errors.New("invalid update options: checkpoint ID is required")
 55→	}
 56→
 57→	sessionIndex, err := s.updateCommittedMain(ctx, opts)
 58→	if err != nil {
 59→		return fmt.Errorf("v2 /main update failed: %w", err)
 60→	}
 61→
 62→	if len(opts.Transcript) > 0 {
 63→		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 64→			return fmt.Errorf("v2 /full/current update failed: %w", err)
 65→		}
 66→	}
 67→
 68→	return nil
 69→}
 70→
 71→// updateCommittedMain updates prompts on the /main ref for an existing checkpoint.
 72→// Returns the session index for coordination with /full/current.
 73→func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
 74→	refName := plumbing.ReferenceName(paths.V2MainRefName)
 75→	parentHash, rootTreeHash, err := s.getRefState(refName)
 76→	if err != nil {
 77→		return 0, ErrCheckpointNotFound
 78→	}
 79→
 80→	basePath := opts.CheckpointID.Path() + "/"
 81→	checkpointPath := opts.CheckpointID.Path()
 82→
 83→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
 84→	if err != nil {
 85→		return 0, err
 86→	}
 87→
 88→	// Read root summary to find session index
 89→	rootMetadataPath := basePath + paths.MetadataFileName
 90→	entry, exists := entries[rootMetadataPath]
 91→	if !exists {
 92→		return 0, ErrCheckpointNotFound
 93→	}
 94→
 95→	summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
 96→	if err != nil {
 97→		return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
 98→	}
 99→	if len(summary.Sessions) == 0 {
100→		return 0, ErrCheckpointNotFound
101→	}
102→
103→	// Find session index by ID, fall back to latest
104→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
105→	if sessionIndex >= len(summary.Sessions) {
106→		// findSessionIndex returns next-available when not found; fall back to latest
107→		sessionIndex = len(summary.Sessions) - 1
108→	}
109→
110→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
111→
112→	// Replace prompts
113→	if len(opts.Prompts) > 0 {
114→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
115→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
116→		if err != nil {
117→			return 0, fmt.Errorf("failed to create prompt blob: %w", err)
118→		}
119→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
120→			Name: sessionPath + paths.PromptFileName,
121→			Mode: filemode.Regular,
122→			Hash: blobHash,
123→		}
124→	}
125→
126→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
127→	if err != nil {
128→		return 0, err
129→	}
130→
131→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
132→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
133→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
134→		return 0, err
135→	}
136→
137→	return sessionIndex, nil
138→}
139→
140→// updateCommittedFullTranscript replaces the transcript on /full/current for a finalized checkpoint.
141→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
142→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
143→	if err := s.ensureRef(refName); err != nil {
144→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
145→	}
146→
147→	parentHash, _, err := s.getRefState(refName)
148→	if err != nil {
149→		return err
150→	}
151→
152→	// Build fresh tree with finalized transcript (replaces previous content)
153→	basePath := opts.CheckpointID.Path() + "/"
154→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
155→
156→	entries := make(map[string]object.TreeEntry)
157→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
158→	if err != nil {
159→		return err
160→	}
161→
162→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
163→		return err
164→	}
165→
166→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
167→	if err != nil {
168→		return fmt.Errorf("failed to build /full/current tree: %w", err)
169→	}
170→
171→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
172→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
173→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
174→}
175→
176→// writeCommittedMain writes metadata entries to the /main ref.
177→// This includes session metadata, prompts, and content hash — but NOT the
178→// raw transcript (full.jsonl), which goes to /full/current.
179→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
180→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
181→	if err := validateWriteOpts(opts); err != nil {
