188→	}
189→
190→	parentHash, rootTreeHash, err := s.getRefState(refName)
191→	if err != nil {
192→		return 0, err
193→	}
194→
195→	basePath := opts.CheckpointID.Path() + "/"
196→	checkpointPath := opts.CheckpointID.Path()
197→
198→	// Read existing entries at this checkpoint's shard path
199→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
200→	if err != nil {
201→		return 0, err
202→	}
203→
204→	// Build main session entries (metadata, prompts, content hash — no transcript)
205→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
206→	if err != nil {
207→		return 0, err
208→	}
209→
210→	// Splice entries into root tree
211→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
212→	if err != nil {
213→		return 0, err
214→	}
215→
216→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
217→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
218→		return 0, err
219→	}
220→	return sessionIndex, nil
221→}
