223→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
224→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
225→// Returns the session index used, for coordination with writeCommittedFullTranscript.
226→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
227→	// Read existing summary to get current session count
228→	var existingSummary *CheckpointSummary
229→	metadataPath := basePath + paths.MetadataFileName
230→	if entry, exists := entries[metadataPath]; exists {
231→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
232→		if err == nil {
233→			existingSummary = existing
234→		}
235→	}
236→
237→	// Determine session index
238→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
239→
240→	// Write session files (metadata, prompts, content hash — no transcript)
241→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
242→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
243→	if err != nil {
244→		return 0, err
245→	}
246→
247→	// Build the sessions array
248→	var sessions []SessionFilePaths
249→	if existingSummary != nil {
250→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
251→		copy(sessions, existingSummary.Sessions)
252→	} else {
253→		sessions = make([]SessionFilePaths, 1)
254→	}
255→	sessions[sessionIndex] = sessionFilePaths
256→
257→	// Write root CheckpointSummary
258→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
259→		return 0, err
260→	}
261→	return sessionIndex, nil
262→}
263→
264→// writeMainSessionToSubdirectory writes a single session's metadata, prompts, and
265→// content hash to a session subdirectory (0/, 1/, 2/, … indexed by session order
266→// within the checkpoint). Unlike the v1 equivalent, this does NOT write the raw
267→// transcript (full.jsonl) — that goes to /full/current.
268→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
269→	filePaths := SessionFilePaths{}
270→
271→	// Clear existing entries at this session path
272→	for key := range entries {
273→		if strings.HasPrefix(key, sessionPath) {
274→			delete(entries, key)
275→		}
276→	}
277→
278→	// Write prompts
279→	if len(opts.Prompts) > 0 {
280→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
281→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
282→		if err != nil {
283→			return filePaths, err
284→		}
285→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
286→			Name: sessionPath + paths.PromptFileName,
287→			Mode: filemode.Regular,
288→			Hash: blobHash,
289→		}
290→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
291→	}
292→
293→	// Write session metadata
294→	sessionMetadata := CommittedMetadata{
295→		CheckpointID:                opts.CheckpointID,
296→		SessionID:                   opts.SessionID,
297→		Strategy:                    opts.Strategy,
298→		CreatedAt:                   time.Now().UTC(),
299→		Branch:                      opts.Branch,
300→		CheckpointsCount:            opts.CheckpointsCount,
301→		FilesTouched:                opts.FilesTouched,
302→		Agent:                       opts.Agent,
303→		Model:                       opts.Model,
304→		TurnID:                      opts.TurnID,
305→		IsTask:                      opts.IsTask,
306→		ToolUseID:                   opts.ToolUseID,
307→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
308→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
309→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart,
310→		TokenUsage:                  opts.TokenUsage,
311→		SessionMetrics:              opts.SessionMetrics,
312→		InitialAttribution:          opts.InitialAttribution,
313→		Summary:                     redactSummary(opts.Summary),
314→		CLIVersion:                  versioninfo.Version,
315→	}
316→
317→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
318→	if err != nil {
319→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
320→	}
321→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
322→	if err != nil {
323→		return filePaths, err
324→	}
325→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
326→		Name: sessionPath + paths.MetadataFileName,
327→		Mode: filemode.Regular,
328→		Hash: metadataHash,
329→	}
330→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
331→
332→	return filePaths, nil
333→}
334→
335→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
336→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
337→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
338→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
339→	if err != nil {
340→		return err
341→	}
342→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
343→		Name: sessionPath + paths.ContentHashFileName,
344→		Mode: filemode.Regular,
345→		Hash: hashBlob,
346→	}
347→	return nil
348→}
349→
350→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
351→// Each write replaces the entire tree — /full/current only ever contains the
352→// transcript for the most recently written checkpoint. Older transcripts are
353→// discarded; generation rotation (future work) will archive them before replacement.
354→//
355→// sessionIndex is the session slot (0-based), determined by the caller to stay
356→// consistent with the /main ref's session numbering.
357→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
358→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
359→	transcript := opts.Transcript
360→	if len(transcript) == 0 && opts.TranscriptPath != "" {
361→		var readErr error
362→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
363→		if readErr != nil {
364→			transcript = nil
365→		}
366→	}
367→	if len(transcript) == 0 {
368→		return nil // No transcript to write
369→	}
370→
371→	if err := validateWriteOpts(opts); err != nil {
372→		return err
373→	}
374→
375→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
376→	if err := s.ensureRef(refName); err != nil {
377→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
378→	}
379→
380→	parentHash, _, err := s.getRefState(refName)
381→	if err != nil {
382→		return err
383→	}
384→
385→	// Build a fresh tree with only this checkpoint's transcript (no accumulation).
386→	basePath := opts.CheckpointID.Path() + "/"
387→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
388→
389→	entries := make(map[string]object.TreeEntry)
390→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
391→	if err != nil {
392→		return err
393→	}
394→
395→	// Write content hash alongside the transcript it references
396→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
397→		return err
398→	}
399→
400→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
401→	if err != nil {
402→		return fmt.Errorf("failed to build /full/current tree: %w", err)
403→	}
404→
405→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
406→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
407→}
408→
409→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
410→// Returns the redacted transcript bytes so the caller can compute the content hash.
411→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
412→	// Redact secrets before chunking
413→	redacted, err := redact.JSONLBytes(transcript)
414→	if err != nil {
415→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
416→	}
417→
418→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
419→	if err != nil {
420→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
421→	}
422→
423→	for i, chunk := range chunks {
424→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
425→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
426→		if err != nil {
427→			return nil, err
428→		}
429→		entries[chunkPath] = object.TreeEntry{
430→			Name: chunkPath,
431→			Mode: filemode.Regular,
432→			Hash: blobHash,
433→		}
434→	}
435→
436→	return redacted, nil
437→}
438→
439→// validateWriteOpts validates identifiers in WriteCommittedOptions.
440→func validateWriteOpts(opts WriteCommittedOptions) error {
441→	if opts.CheckpointID.IsEmpty() {
442→		return errors.New("invalid checkpoint options: checkpoint ID is required")
443→	}
444→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
445→		return fmt.Errorf("invalid checkpoint options: %w", err)
446→	}
447→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
448→		return fmt.Errorf("invalid checkpoint options: %w", err)
449→	}
450→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
451→		return fmt.Errorf("invalid checkpoint options: %w", err)
452→	}
453→	return nil
454→}
455→

