 45→// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
 46→// Called at stop time to finalize checkpoints with the complete session transcript.
 47→//
 48→// On /main: replaces prompts (transcript is not stored there).
 49→// On /full/current: replaces the raw transcript (if provided).
 50→//
 51→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
 52→func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
 53→	if opts.CheckpointID.IsEmpty() {
 54→		return errors.New("invalid update options: checkpoint ID is required")
 55→	}
 56→
 57→	sessionIndex, err := s.updateCommittedMain(ctx, opts)
 58→	if err != nil {
 59→		return fmt.Errorf("v2 /main update failed: %w", err)
 60→	}
 61→
 62→	if len(opts.Transcript) > 0 {
 63→		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 64→			return fmt.Errorf("v2 /full/current update failed: %w", err)
 65→		}
 66→	}
 67→
 68→	return nil
 69→}
