176→// writeCommittedMain writes metadata entries to the /main ref.
177→// This includes session metadata, prompts, and content hash — but NOT the
178→// raw transcript (full.jsonl), which goes to /full/current.
179→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
180→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
181→	if err := validateWriteOpts(opts); err != nil {
182→		return 0, err
