409→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
410→// Returns the redacted transcript bytes so the caller can compute the content hash.
411→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
412→	// Redact secrets before chunking
413→	redacted, err := redact.JSONLBytes(transcript)
414→	if err != nil {
415→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
416→	}
417→
418→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
419→	if err != nil {
420→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
421→	}
422→
423→	for i, chunk := range chunks {
424→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
425→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
426→		if err != nil {
427→			return nil, err
428→		}
429→		entries[chunkPath] = object.TreeEntry{
430→			Name: chunkPath,
431→			Mode: filemode.Regular,
432→			Hash: blobHash,
433→		}
434→	}
435→
