	v2Store := cpkg.NewV2GitStore(repo)
	if err := v2Store.UpdateCommitted(ctx, opts); err != nil {
		logging.Warn(ctx, "v2 dual-write update failed",
			slog.String("checkpoint_id", opts.CheckpointID.String()),
			slog.String("error", err.Error()),
		)
	}
}

